import {renderDocument} from './renderer.js';
import {downloadBlob} from './storage.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createPlatformStudio(api){
 const desktop=globalThis.window?.lumaDesktop;
 const status=s=>{const e=$('#canva-status');if(e)e.textContent=s;};
 let mounted=false,working=false,continuation='',seen=new Set();
 async function job(run){if(working)return;working=true;document.querySelectorAll('[data-canva-operation]').forEach(b=>b.disabled=true);try{await run();}catch(e){status(String(e.message||e).replace(/^Error invoking remote method '[^']+': Error: /,''));}finally{working=false;if(mounted)document.querySelectorAll('[data-canva-operation]').forEach(b=>b.disabled=false);}}
 function openCanva(){
  mounted=true;continuation='';seen=new Set();
  const content=`<div class="platform-hero"><span class="live-pill">CANVA CONNECT</span><h3>Từ bản gốc đến bản chỉnh sửa.</h3><p>Mở thiết kế native trong Canva, lấy từng trang về Luma để retouch, rồi gửi ảnh đã sửa vào thiết kế Canva mới.</p></div><div class="platform-grid"><section><div class="platform-section-title"><h3>Thư viện Canva</h3><span id="canva-connection" class="platform-badge">${desktop?'Chưa đọc phiên':'Cần bản Windows'}</span></div><div class="platform-search"><input id="canva-query" placeholder="Tìm tên thiết kế…" aria-label="Tìm thiết kế Canva"><button class="button" data-canva-operation id="canva-search" ${desktop?'':'disabled'}>Tìm</button></div><div id="canva-designs" class="canva-designs"><div class="platform-empty">${desktop?'Kết nối tài khoản để xem các thiết kế của bạn.':'Mở bản Windows để kết nối Canva. Bản web có thể nhập tệp PPTX / SVG bạn tải xuống.'}</div></div><button class="button" data-canva-operation id="canva-more" hidden>Xem thêm</button><p id="canva-status" class="advanced-status" role="status">${desktop?'Thông tin đăng nhập do bạn nhập ở cấu hình bên phải.':'Bạn vẫn có thể sửa ảnh và nhập thiết kế đã xuất.'}</p></section><aside><h3>Luồng làm việc</h3><ol class="platform-steps"><li><strong>Mở native</strong><p>Mở đúng tài liệu trong trình sửa Canva; giữ các thành phần native ở đó.</p></li><li><strong>Retouch trong Luma</strong><p>Chọn trang PNG nguyên kích thước. Trang được nhập thành một lớp ảnh, không phải cây layer Canva.</p></li><li><strong>Gửi trở lại</strong><p>Tạo thiết kế Canva mới chứa ảnh đã sửa. Bạn có thể dùng ảnh trong tài liệu gốc.</p></li></ol><button class="button primary" data-canva-operation id="canva-connect" ${desktop?'':'disabled'}>Kết nối tài khoản Canva</button><button class="button" data-canva-operation id="canva-send" ${desktop?'':'disabled'}>Gửi ảnh hiện tại sang Canva</button><button class="button" data-canva-operation id="canva-disconnect" ${desktop?'':'disabled'}>Ngắt kết nối</button><details class="platform-config"><summary>Cấu hình Canva Developer</summary><p>Dành cho chủ ứng dụng hoặc người dùng có app Canva riêng. Bản phân phối không chứa Client secret. Cấu hình app công khai cần hoàn tất xét duyệt của Canva và máy chủ giữ bí mật.</p><label class="modal-field">Client ID<input id="canva-client-id" autocomplete="off" spellcheck="false"></label><label class="modal-field">Client secret<input id="canva-client-secret" type="password" autocomplete="off"></label><p>Đăng ký Redirect URL này trong Canva:</p><code class="platform-uri">http://127.0.0.1:47831/canva/callback</code><p>Scopes: design:meta:read, design:content:read, design:content:write, asset:read, asset:write. Secret chỉ ở bộ nhớ trong phiên. Token được mã hóa bằng kho hệ điều hành khi khả dụng.</p><button class="button" data-canva-operation id="canva-configure" ${desktop?'':'disabled'}>Áp dụng cấu hình</button></details><p class="gen-size-note">Giấy phép tài nguyên và giới hạn gói Canva vẫn áp dụng. Không có parser .canva offline hoặc đồng bộ layer hai chiều trong Luma.</p></aside></div>`;
  api.showModal('Canva · tài liệu & retouch','Luma Studio 9 · Larx Vo · vovinhlac.com',content,[{label:'Nhập PPTX / SVG',run:()=>{api.closeModal();api.runAction('design-import');}},{label:'Đóng',primary:true,run:()=>api.closeModal()}],()=>{
   if(!desktop)return;
   const connection=s=>{if(!mounted)return;$('#canva-connection').textContent=s.connected?'Đã kết nối':s.configured?'Đã cấu hình':'Chưa cấu hình';$('#canva-client-id').value=s.clientId||'';};
   async function list(more=false){status('Đang đọc thiết kế…');const result=await desktop.canva('list',{query:$('#canva-query').value,continuation:more?continuation:''});if(!mounted)return;if(!more){$('#canva-designs').innerHTML='';seen.clear();}continuation=result.continuation;for(const d of result.items){if(seen.has(d.id))continue;seen.add(d.id);const card=document.createElement('article');card.className='canva-design-card';card.innerHTML=`${d.thumbnail?`<img src="${esc(d.thumbnail)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:'<div class="canva-placeholder">Canva</div>'}<div><strong>${esc(d.title)}</strong><small>${esc(d.id)}</small><label>Trang <input class="canva-page" type="number" min="1" max="10000" value="1" aria-label="Trang thiết kế ${esc(d.title)}"></label><div><button class="button" data-canva-operation data-native-open>Mở native ↗</button><button class="button" data-canva-operation data-canva-import>Về Luma</button></div></div>`;card.querySelector('[data-native-open]').onclick=()=>job(async()=>{status('Đang mở trình sửa Canva…');await desktop.canva('open',{id:d.id});status('Canva đã mở trong trình duyệt. Sửa xong, quay lại Luma và chọn Về Luma để lấy trang mới nhất.');});card.querySelector('[data-canva-import]').onclick=()=>job(async()=>{const page=Number(card.querySelector('.canva-page').value);status('Canva đang xuất trang PNG…');const result=await desktop.canva('export',{id:d.id,page});if(!mounted)return;const opened=await api.openFiles([new File([result.bytes],result.name,{type:'image/png'})]);if(!opened?.length)throw Error('Không mở được ảnh Canva. Tài liệu hiện tại được giữ nguyên.');const doc=opened[0];doc.canvaSource={designId:result.designId,page:result.page,importedAt:new Date().toISOString(),representation:'flattened-png'};api.commit('Nhập trang Canva');api.closeModal();api.toast('Đã nhập trang Canva. Chọn lớp rồi retouch như ảnh thường.');});$('#canva-designs').append(card);}if(!seen.size)$('#canva-designs').innerHTML='<div class="platform-empty">Chưa tìm thấy thiết kế.</div>';$('#canva-more').hidden=!continuation;status('Đã đọc '+seen.size+' thiết kế.');}
   $('#canva-configure').onclick=()=>job(async()=>{connection(await desktop.canva('configure',{clientId:$('#canva-client-id').value.trim(),clientSecret:$('#canva-client-secret').value}));$('#canva-client-secret').value='';status('Đã cấu hình cho phiên này. Chọn Kết nối tài khoản Canva.');});
   $('#canva-connect').onclick=()=>job(async()=>{status('Hoàn tất đăng nhập và cấp quyền trong trình duyệt…');connection(await desktop.canva('connect'));if(mounted)await list();});
   $('#canva-disconnect').onclick=()=>job(async()=>{connection(await desktop.canva('disconnect'));if(mounted){$('#canva-designs').innerHTML='<div class="platform-empty">Đã ngắt kết nối và xóa token tại máy này.</div>';status('Đã ngắt kết nối.');}});
   $('#canva-search').onclick=()=>job(()=>list());$('#canva-more').onclick=()=>job(()=>list(true));$('#canva-query').onkeydown=e=>{if(e.key==='Enter')job(()=>list());};
   $('#canva-send').onclick=()=>job(async()=>{const d=api.doc();if(!d)throw Error('Mở ảnh trước khi gửi.');status('Đang xuất ảnh và gửi sang Canva…');const c=renderDocument(d,api.assets),blob=await new Promise(r=>c.toBlob(r,'image/png'));if(!blob)throw Error('Không xuất được ảnh.');await desktop.canva('send',{bytes:new Uint8Array(await blob.arrayBuffer()),name:d.name,width:d.width,height:d.height});status('Đã tạo thiết kế Canva mới và mở trình sửa. Nội dung gửi là ảnh gộp của tài liệu Luma.');});
   job(async()=>{const s=await desktop.canva('status');connection(s);if(s.connected)await list();});
  },()=>{mounted=false;});
 }
 function compatibility(){api.showModal('Định dạng & kiểm chứng','Phạm vi thực tế của Luma Studio 9',`<div class="platform-hero"><span class="live-pill">LUMA STUDIO 9</span><h3>Sửa được gì, giữ được gì.</h3><p>Được tạo bởi <strong>Larx Vo</strong> · <a href="https://vovinhlac.com" target="_blank" rel="noopener">vovinhlac.com</a> · Miễn phí sử dụng.</p></div><div class="compatibility-table"><table><thead><tr><th>Hạng mục</th><th>Khả năng hiện tại</th><th>Giới hạn cần biết</th></tr></thead><tbody><tr><th>Windows</th><td>Bộ cài NSIS x64; chạy editor và model ONNX đi kèm tại máy.</td><td>Bản chưa ký số; xem báo cáo phát hành về môi trường đã kiểm tra.</td></tr><tr><th>PSD / PSB</th><td>RGB 8-bit; pixel, nhóm, mask, alpha, paths, chữ được hỗ trợ, Smart Objects và một số Smart Filters.</td><td>Không tương thích toàn bộ Photoshop. Warp, hiệu ứng và các cấu trúc chưa hỗ trợ dùng composite nếu có.</td></tr><tr><th>Smart Filters</th><td>Gaussian Blur, Unsharp Mask, High Pass, Invert trong tập điều kiện tương thích.</td><td>Mask riêng / blend / opacity của filter chưa được hỗ trợ; phép lọc Luma có thể khác Photoshop.</td></tr><tr><th>Canva native</th><td>Kết nối OAuth, tìm thiết kế, mở bản gốc trong Canva, lấy trang về Luma và gửi ảnh sang Canva.</td><td>Cần cấu hình app Canva. Trang về Luma là PNG gộp; không sửa toàn bộ layer Canva offline.</td></tr><tr><th>Màu in</th><td>Soft proof và TIFF CMYK có ICC qua LittleCMS; giữ kích thước pixel và DPI đã chọn.</td><td>Engine biên tập RGB 8-bit. Chưa có engine PSD CMYK / 16-bit / 32-bit.</td></tr><tr><th>GPU AI</th><td>Probe phần cứng, kiểm chứng CUDA tensor, chạy job và xuất ảnh đối chiếu / metric.</td><td>Chỉ xác nhận GPU sau khi chạy thật trên máy có CUDA. Kiểm thử CPU hoặc tên GPU do máy chủ báo chưa đủ.</td></tr></tbody></table></div><p class="gen-size-note">Ảnh lớn được mở theo bộ nhớ và giới hạn canvas của máy, không chặn theo số MB. Chi tiết đã mất do nước / rách không thể xác nhận là bản gốc nếu không có tư liệu.</p>`,[{label:'Canva',run:openCanva},{label:'Kiểm chứng AI',run:()=>{api.closeModal();api.runAction('ai-verify');}},{label:'Đóng',primary:true,run:()=>api.closeModal()}]);}
 if(desktop){desktop.onOpen(async files=>{await api.openFiles(files.map(f=>new File([f.bytes],f.name)));});desktop.onAction?.(action=>{if(['undo','redo'].includes(action))api.runAction(action);});}
 return{openCanva,compatibility};
}
